svg.script:
(function() {
  // =========================================================================
  // 1. CONFIGURATION & ANIMATION DU TEXTE BINAIRE
  // =========================================================================
  window.BINAIRE_CONFIG = {
    // Multiplicateur de vitesse (1.0 = normal, 2.0 = 2x plus rapide, 0.5 = 2x plus lent)
    vitesse: 1.0,

    // Intervalle de base entre chaque nouvelle ligne defilante en ms (pour vitesse = 1.0)
    // 120ms = ~8 lignes par seconde (defilement dynamique et fluide)
    intervalleBaseMs: 120,

    // Longueur exacte de chaque ligne binaire (15 caracteres '0' et '1')
    longueurLigne: 15,

    // Direction du defilement : 'haut' (le texte monte) ou 'bas' (le texte descend)
    direction: 'haut',

    // Probabilite d'apparition de '1' (0.5 = equilibre 50% de 1 et 50% de 0)
    ratioUn: 0.5,

    // Methode pour ajuster la vitesse dynamiquement
    setVitesse: function(nouvelleVitesse) {
      var v = parseFloat(nouvelleVitesse);
      if (!isNaN(v) && v > 0) {
        this.vitesse = v;
      }
    }
  };

  // Raccourci global
  window.setVitesseBinaire = function(v) {
    window.BINAIRE_CONFIG.setVitesse(v);
  };

  function genererLigneBinaire(longueur, ratio) {
    var str = '';
    for (var i = 0; i < longueur; i++) {
      str += Math.random() < ratio ? '1' : '0';
    }
    return str;
  }

  function initAnimationBinaire() {
    var textElem = document.getElementById('binaire');
    if (!textElem) return;

    // Recuperation de la vitesse depuis l'attribut data-vitesse si present
    var customSpeed = textElem.getAttribute('data-vitesse') || document.documentElement.getAttribute('data-vitesse-binaire');
    if (customSpeed) {
      window.BINAIRE_CONFIG.setVitesse(customSpeed);
    }

    var tspans = textElem.querySelectorAll('tspan');
    if (!tspans || tspans.length === 0) return;

    var config = window.BINAIRE_CONFIG;
    var lignes = [];

    // Initialiser toutes les lignes avec des chaines binaires aleatoires de longueur 15
    for (var i = 0; i < tspans.length; i++) {
      var existant = tspans[i].textContent.trim();
      if (existant.length === config.longueurLigne && /^[01]+$/.test(existant)) {
        lignes.push(existant);
      } else {
        lignes.push(genererLigneBinaire(config.longueurLigne, config.ratioUn));
      }
      tspans[i].textContent = lignes[i] + '\n';
    }

    function defilerLigne() {
      var nouvelleLigne = genererLigneBinaire(config.longueurLigne, config.ratioUn);
      if (config.direction === 'bas') {
        lignes.pop();
        lignes.unshift(nouvelleLigne);
      } else {
        lignes.shift();
        lignes.push(nouvelleLigne);
      }

      for (var j = 0; j < tspans.length; j++) {
        tspans[j].textContent = lignes[j] + '\n';
      }
    }

    var dernierTemps = performance.now();
    var tempsEcoule = 0;

    function boucleBinaire(tempsActuel) {
      var delta = tempsActuel - dernierTemps;
      dernierTemps = tempsActuel;

      var vitesse = Math.max(0.01, config.vitesse);
      var intervalleActuel = config.intervalleBaseMs / vitesse;

      tempsEcoule += delta;

      if (tempsEcoule >= intervalleActuel) {
        var nbPas = Math.min(5, Math.floor(tempsEcoule / intervalleActuel));
        tempsEcoule -= nbPas * intervalleActuel;
        for (var p = 0; p < nbPas; p++) {
          defilerLigne();
        }
      }

      requestAnimationFrame(boucleBinaire);
    }

    requestAnimationFrame(boucleBinaire);
  }


  // =========================================================================
  // 2. CONFIGURATION & ANIMATION DES LUMIERES
  // =========================================================================
  window.LUMIERES_CONFIG = {
    // Multiplicateur de vitesse (1.0 = normal, 2.0 = 2x plus rapide, 0.5 = 2x plus lent)
    vitesse: 1.0,

    // Palette de couleurs demandees : 4fb8d0ff (#4fb8d0), b4eeeeff (#b4eeee), 284397ff (#284397)
    couleurs: ['#4fb8d0', '#b4eeee', '#284397'],

    // Plage d'opacite aleatoire (entre 0.15 et 1.0)
    opaciteMin: 0.15,
    opaciteMax: 1.0,

    // Duree de la transition en ms (a vitesse normale = 1.0)
    dureeTransitionMin: 300,
    dureeTransitionMax: 800,

    // Delai d'attente / pause entre deux changements en ms (a vitesse normale = 1.0)
    delaiMin: 150,
    delaiMax: 900,

    // Methode pour changer la vitesse dynamiquement
    setVitesse: function(nouvelleVitesse) {
      var v = parseFloat(nouvelleVitesse);
      if (!isNaN(v) && v > 0) {
        this.vitesse = v;
      }
    }
  };

  // Raccourci global
  window.setVitesseLumieres = function(v) {
    window.LUMIERES_CONFIG.setVitesse(v);
  };

  function animerRectangle(rect) {
    var config = window.LUMIERES_CONFIG;
    var vitesse = Math.max(0.01, config.vitesse);

    // Selection aleatoire d'une couleur dans la palette
    var couleur = config.couleurs[Math.floor(Math.random() * config.couleurs.length)];

    // Selection aleatoire d'une opacite
    var opacite = config.opaciteMin + Math.random() * (config.opaciteMax - config.opaciteMin);

    // Duree de la transition et delai de pause adaptes selon la vitesse
    var duree = Math.round((config.dureeTransitionMin + Math.random() * (config.dureeTransitionMax - config.dureeTransitionMin)) / vitesse);
    var delai = Math.round((config.delaiMin + Math.random() * (config.delaiMax - config.delaiMin)) / vitesse);

    // Application de la transition CSS fluide sur l'opacite et la couleur de remplissage
    rect.style.transition = 'opacity ' + duree + 'ms ease-in-out, fill ' + duree + 'ms ease-in-out';
    rect.style.fillOpacity = '1';
    rect.style.opacity = opacite.toFixed(3);
    rect.style.fill = couleur;

    // Planification du prochain cycle pour ce rectangle
    setTimeout(function() {
      animerRectangle(rect);
    }, duree + delai);
  }

  function initAnimationLumieres() {
    var lumieresGroup = document.getElementById('lumieres');
    if (!lumieresGroup) return;

    var customSpeed = lumieresGroup.getAttribute('data-vitesse') || document.documentElement.getAttribute('data-vitesse-lumieres');
    if (customSpeed) {
      window.LUMIERES_CONFIG.setVitesse(customSpeed);
    }

    var rects = lumieresGroup.querySelectorAll('rect');
    for (var i = 0; i < rects.length; i++) {
      (function(r) {
        var initialDelay = Math.random() * 1200 / Math.max(0.01, window.LUMIERES_CONFIG.vitesse);
        setTimeout(function() {
          animerRectangle(r);
        }, initialDelay);
      })(rects[i]);
    }
  }


  // =========================================================================
  // INITIALISATION GLOBALE
  // =========================================================================
  function initialiserTout() {
    initAnimationBinaire();
    initAnimationLumieres();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initialiserTout);
  } else {
    initialiserTout();
  }
})();
